export const printCss = ".dve-print-pages {\n\tdisplay: flex;\n\tflex-direction: column;\n\talign-items: center;\n\tgap: 24px;\n\tmargin: 0 auto;\n\tzoom: var(--dve-zoom, 1);\n}\n.dve-print-pages[hidden] {\n\tdisplay: none;\n}\n.dve-print-page {\n\tposition: relative;\n\tflex: none;\n\tbackground: var(--dve-page-color, #fff);\n\tcolor: #202124;\n\tbox-shadow:\n\t\t0 1px 3px #20212430,\n\t\t0 4px 12px #20212420;\n\toverflow: hidden;\n}\n.dve-print-column {\n\tposition: absolute;\n\tz-index: 1;\n}\n/* Floating pictures sit in front of text unless anchored behind it (wp:anchor/@behindDoc). */\n.dve-print-float {\n\tz-index: 2;\n}\n.dve-print-float-behind {\n\tz-index: 0;\n}\n.dve-print-picture-missing {\n\tbox-sizing: border-box;\n\tborder: 1px dashed #8a8886;\n\tbackground: #f3f2f1;\n}\n.dve-print-chart {\n\toverflow: hidden;\n\tbackground: #fff;\n}\n.dve-print-chart > svg {\n\tdisplay: block;\n\twidth: 100%;\n\theight: 100%;\n}\n.dve-print-chart-frame {\n\tdisplay: grid;\n\tplace-items: center;\n\tcolor: #605e5c;\n\tfont-size: 11px;\n}\n.dve-print-block {\n\tposition: absolute;\n\tleft: 0;\n\twidth: 100%;\n}\n.dve-print-line {\n\tposition: absolute;\n\tleft: 0;\n\twidth: 100%;\n\tfont:\n\t\t11pt/1.2 Calibri,\n\t\tArial,\n\t\tsans-serif;\n\tcursor: text;\n}\n.dve-print-line span {\n\tposition: absolute;\n\ttop: 0;\n}\n.dve-print-row {\n\tposition: absolute;\n\tleft: 0;\n\twidth: 100%;\n}\n/* Cells sit at their grid positions; borders come from the document (Word prints no gridlines). */\n.dve-print-cell {\n\tposition: absolute;\n\ttop: 0;\n\tbox-sizing: border-box;\n}\n.dve-print-cell-content {\n\tposition: absolute;\n\tbottom: 0;\n}\n@media print {\n\t.dve-ribbon,\n\t.dve-status,\n\t.multilingual-controls {\n\t\tdisplay: none !important;\n\t}\n\t.dve-canvas {\n\t\toverflow: visible !important;\n\t\tpadding: 0 !important;\n\t}\n\t.dve-paper {\n\t\tdisplay: none !important;\n\t}\n\t.dve-print-pages {\n\t\tgap: 0 !important;\n\t\tzoom: 1 !important;\n\t}\n\t.dve-print-page {\n\t\t/* Like Word, page colours are not printed unless asked for. */\n\t\tbackground: #fff !important;\n\t\tbox-shadow: none !important;\n\t\tbreak-after: page;\n\t}\n}\n.dve-print-header,\n.dve-print-footer {\n\tposition: absolute;\n\tcolor: var(--ink);\n\tfont-size: 11pt;\n\tpointer-events: none;\n}\n.dve-print-header p,\n.dve-print-footer p {\n\tmargin: 0;\n}\n.dve-print-header table,\n.dve-print-footer table {\n\twidth: 100%;\n\tborder-collapse: collapse;\n}\n\n/* Complex field begin/code/separate/end markers: kept in the document, never shown. */\n.dve-field-marker {\n\tdisplay: inline;\n\tfont-size: 0;\n}\n\n/* TOC entries link to hidden _Toc bookmarks; Word draws them in the entry's style, not as links. */\na.dve-link[data-anchor^='_Toc'] {\n\tcolor: inherit;\n\ttext-decoration: none;\n}\n\n/* Tabs sized to Word's tab stops by tab-stops-view.ts; leaders fill the tab's width. */\n.dve-tab {\n\tdisplay: inline-block;\n\toverflow: hidden;\n\twhite-space: pre;\n\tvertical-align: baseline;\n\ttext-indent: 0;\n}\n.dve-tab-leader-dot,\n.dve-tab-leader-middleDot {\n\tbackground-image: radial-gradient(circle, currentColor 0.8px, transparent 1.1px);\n\tbackground-size: 4px 4px;\n\tbackground-repeat: repeat-x;\n\tbackground-position: right 0 bottom 0.25em;\n}\n.dve-tab-leader-hyphen {\n\tbackground-image: linear-gradient(to right, currentColor 50%, transparent 50%);\n\tbackground-size: 6px 1px;\n\tbackground-repeat: repeat-x;\n\tbackground-position: right 0 bottom 0.4em;\n}\n.dve-tab-leader-underscore,\n.dve-tab-leader-heavy {\n\tborder-bottom: 1px solid currentColor;\n}\n.dve-tab-leader-heavy {\n\tborder-bottom-width: 2px;\n}\n\n/* Footnotes above the bottom margin; the separator is Word's 2-inch rule. */\n.dve-print-footnotes {\n\tposition: absolute;\n\tz-index: 1;\n}\n.dve-print-footnote-separator {\n\tposition: absolute;\n\ttop: -7px;\n\tleft: 0;\n\twidth: 192px;\n\tborder-top: 1px solid currentColor;\n}\n.dve-print-footnote {\n\tposition: absolute;\n\tleft: 0;\n\twidth: 100%;\n}\n\n[data-print-view] .dve-notes-container {\n\tdisplay: none;\n}\n\n/* Word draws superscript and subscript at about two thirds size without growing the line. */\n.dve-paper sup,\n.dve-paper sub {\n\tfont-size: 0.65em;\n\tline-height: 0;\n}\n/* Exact-height rows clip content that does not fit, as Word does. */\n.dve-print-cell {\n\toverflow: hidden;\n}\n.dve-print-paragraph-frame {\n\tposition: absolute;\n\ttop: 0;\n\tbox-sizing: border-box;\n}\n\n/* View > Multiple Pages: Print Layout's sheets sit side by side and wrap, instead of one column. */\n.dve-canvas[data-multipage] .dve-print-pages {\n\tflex-direction: row;\n\tflex-wrap: wrap;\n\talign-items: flex-start;\n\tjustify-content: center;\n}\n\n/* Layout > Line Numbers: numbers in the left margin, one per printed line. */\n.dve-print-line-number {\n\tposition: absolute;\n\twidth: 40px;\n\ttext-align: right;\n\tfont:\n\t\t10px 'Segoe UI',\n\t\tArial,\n\t\tsans-serif;\n\tcolor: #444;\n\tpointer-events: none;\n}\n";
